CREATE TABLE `machine_rate_history` (
	`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL,
	`machine_type_id` integer NOT NULL,
	`rate_cents` integer,
	`valid_from` text NOT NULL,
	`source` text NOT NULL,
	`note` text DEFAULT '' NOT NULL,
	`created_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) NOT NULL,
	`updated_at` text DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ', 'now')) NOT NULL,
	`created_by` text NOT NULL,
	`updated_by` text NOT NULL,
	FOREIGN KEY (`machine_type_id`) REFERENCES `machine_types`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "machine_rate_history_source_check" CHECK(source IN ('form', 'import', 'po', 'migration', 'revert')),
	CONSTRAINT "machine_rate_history_rate_check" CHECK("machine_rate_history"."rate_cents" IS NULL OR "machine_rate_history"."rate_cents" >= 0)
);
--> statement-breakpoint
